-- STEPUP legal policy drafts. This migration is additive and is NOT run automatically.
-- Policies start as drafts and are never publicly served until an administrator publishes them.
BEGIN;

INSERT INTO public.store_settings (setting_key, setting_value, description)
VALUES (
  'legal_policies',
  '{
    "policies": [
      {"slug":"privacy","title":"Privacy Policy","status":"draft","content":"DRAFT — COMPANY REVIEW REQUIRED\n\n1. Who operates this website\n[COMPANY LEGAL NAME, REGISTERED/PRINCIPAL ADDRESS AND PRIVACY CONTACT — REQUIRED BEFORE PUBLICATION]\n\n2. Information we handle\nAccount and contact details, delivery details, order and payment status, customer-support messages, and information you choose to provide in fit or comfort questionnaires. Do not submit medical records or sensitive health details unless the feature expressly asks for them and the company has approved the collection and safeguards.\n\n3. Why information is used\nTo create accounts, fulfil orders, process payments and returns, provide support, maintain security, and operate fit-related features you choose to use. Marketing must be optional and separately controllable.\n\n4. Sharing and service providers\nInformation may be shared only as needed with payment, hosting, delivery, communications and support providers, subject to appropriate contracts and safeguards. Do not store full card credentials or UPI PINs.\n\n5. Choices, access and deletion\nProvide a clear channel for privacy requests, consent withdrawal where applicable, account closure and correction requests. Retain records only as long as required for the stated purpose or applicable law.\n\n6. Security and incidents\nUse access controls, encryption in transit, least privilege, audit logging, backups and an incident-response process.\n\n7. Children\nThe service is intended for adults. Do not knowingly collect children’s personal data without the legally required verifiable parental consent and safeguards.\n\n8. Contact and effective date\n[PRIVACY CONTACT, GRIEVANCE OFFICER DETAILS, EFFECTIVE DATE AND RETENTION SCHEDULE — REQUIRED BEFORE PUBLICATION]"},
      {"slug":"terms","title":"Terms of Use","status":"draft","content":"DRAFT — COMPANY REVIEW REQUIRED\n\n1. Operator and acceptance\n[COMPANY LEGAL NAME AND ADDRESS — REQUIRED BEFORE PUBLICATION]. These terms govern use of the STEPUP website. Purchase consent must be explicit and affirmative; no pre-ticked acceptance.\n\n2. Product information and availability\nProduct descriptions, sizes, images, stock and prices should reflect current catalogue data. Orders are subject to availability and confirmation. Any material correction must be communicated transparently; statutory consumer rights are not excluded.\n\n3. Pricing, taxes and payment\nAll prices and checkout totals are shown in INR. Applicable taxes and shipping charges must be disclosed before order placement. Payment processing is handled by the selected payment provider. Never ask customers to disclose OTPs, UPI PINs or card PINs to STEPUP.\n\n4. Orders and cancellation\nOrder confirmation, cancellation eligibility and any lawful charges must be explained clearly. Do not impose a cancellation charge on a customer unless equivalent charges apply when the business unilaterally cancels.\n\n5. Returns, refunds and complaints\nSee the published Return & Refund Policy. Nothing in these terms removes rights available under consumer law.\n\n6. Fit and health information\nFit tools and comfort descriptions are general shopping information, not diagnosis, treatment, medical advice or a substitute for a qualified healthcare professional. Product suitability varies by individual. Stop using a product if it causes discomfort and seek appropriate professional advice for persistent symptoms.\n\n7. Reviews and acceptable use\nReviews must reflect genuine experience. Fake, purchased or selectively manipulated reviews are not permitted. Users must not misuse the website, attempt unauthorised access or submit unlawful content.\n\n8. Contact, governing law and effective date\n[LEGAL ENTITY, CUSTOMER CARE/GRIEVANCE CONTACT, JURISDICTION REVIEW AND EFFECTIVE DATE — REQUIRED BEFORE PUBLICATION]"},
      {"slug":"shipping","title":"Shipping & Delivery Policy","status":"draft","content":"DRAFT — COMPANY OPERATIONS MUST CONFIRM BEFORE PUBLICATION\n\n1. Delivery coverage\n[CONFIRM SERVICEABLE PIN CODES, EXCLUSIONS AND DELIVERY PARTNERS]. Do not promise delivery to an area until serviceability is confirmed at checkout.\n\n2. Dispatch and delivery estimates\n[CONFIRM ORDER PROCESSING TIME, CARRIER HANDOVER TIME AND PIN-CODE-BASED ESTIMATED DELIVERY WINDOWS]. Display estimates before payment and explain that exceptional carrier or weather delays may occur.\n\n3. Shipping charges\nShow the exact shipping charge and any free-shipping threshold before the customer places the order. These values must match the live database checkout settings.\n\n4. Tracking and failed delivery\nProvide tracking when supplied by the carrier. Explain attempted delivery, incorrect address, refusal and return-to-origin handling without inventing fees.\n\n5. Damaged, missing or delayed parcels\nProvide a customer-support route for reporting delivery problems and explain the evidence reasonably needed to investigate.\n\n6. Contact\n[OFFICIAL CUSTOMER CARE CONTACT AND GRIEVANCE OFFICER — REQUIRED BEFORE PUBLICATION]"},
      {"slug":"returns","title":"Returns, Exchanges & Refund Policy","status":"draft","content":"DRAFT — COMPANY OPERATIONS MUST CONFIRM BEFORE PUBLICATION\n\n1. Eligibility and time window\n[COMPANY MUST SET A REALISTIC RETURN/EXCHANGE WINDOW, STARTING EVENT AND ELIGIBILITY RULES]. Do not publish a blanket no-return rule that removes statutory remedies for defective, deficient, spurious, misdescribed or materially late goods.\n\n2. Condition and packaging\n[CONFIRM whether tried-on footwear, tags, original packaging and accessories are required; define hygiene/safety exceptions narrowly and lawfully].\n\n3. How to request a return\n[ADD CUSTOMER PORTAL/EMAIL/PHONE PROCESS, REQUIRED ORDER DETAILS AND PICKUP/SELF-SHIP PROCESS]. Issue a trackable complaint/return reference.\n\n4. Return shipping and exchanges\n[CONFIRM who bears return shipping in each scenario, exchange availability, size exchange rules and any limits]. Do not charge undisclosed fees.\n\n5. Refund method and timing\nRefunds should be made through the original payment method where practicable and within the applicable legal/payment-system timelines. [CONFIRM operational processing SLA; do not promise a timeline until verified]. COD refund method and verification process must be explained.\n\n6. Damaged, defective, incorrect or misdescribed products\nProvide a clear remedy and escalation path consistent with consumer law. Do not require customers to waive legal rights.\n\n7. Complaints and grievance redressal\nAcknowledge complaints within 48 hours and resolve within one month, consistent with the applicable e-commerce rules. [ADD NAMED GRIEVANCE OFFICER AND OFFICIAL CONTACT DETAILS BEFORE PUBLICATION]."}
    ],
    "business_identity": {"legal_name":"","registered_address":"","customer_care_email":"","customer_care_phone":"","grievance_officer_name":"","grievance_officer_designation":"","grievance_email":"","grievance_phone":"","gstin":"","gst_status":"unverified"},
    "operational_confirmation": {"shipping_coverage":"","dispatch_sla":"","delivery_estimate":"","return_window_days":null,"return_conditions":"","return_shipping_rule":"","refund_sla":"","cod_refund_method":"","confirmed_by":"","confirmed_at":null},
    "last_reviewed_at":null
  }'::jsonb,
  'Draft legal policies and business disclosures. Drafts are private until published after company/legal review.'
)
ON CONFLICT (setting_key) DO NOTHING;

COMMIT;
